export const taxSettings = pgTable(
  "tax_settings",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    singleton: boolean().default(true).notNull(),
    pricesIncludeTax: boolean("prices_include_tax").default(true).notNull(),
    rateBps: integer("rate_bps").default(0).notNull(),
    label: text().default("Tax").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true, mode: "date" }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true, mode: "date" }).defaultNow().notNull(),
  },
  (table) => [
    unique("tax_settings_singleton_key").on(table.singleton),
    check("tax_settings_rate_bps_check", sql`(rate_bps >= 0) AND (rate_bps <= 10000)`),
    check("tax_settings_singleton_check", sql`CHECK (singleton)`),
  ],
);

export const paymentMethods = pgTable(
  "payment_methods",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    code: text().notNull(),
    name: text().notNull(),
    instructions: text(),
    enabled: boolean().default(false).notNull(),
    position: integer().default(0).notNull(),
    createdAt: timestamp("created_at", { withTimezone: true, mode: "date" }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true, mode: "date" }).defaultNow().notNull(),
  },
  (table) => [
    unique("payment_methods_code_key").on(table.code),
    check("payment_methods_code_check", sql`code ~ '^[a-z_]+$'::text`),
  ],
);

export const discountCodes = pgTable(
  "discount_codes",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    code: text().notNull(),
    kind: discountKind().notNull(),
    value: integer().default(0).notNull(),
    minSubtotal: integer("min_subtotal").default(0).notNull(),
    usageLimit: integer("usage_limit"),
    perCustomerLimit: integer("per_customer_limit"),
    usedCount: integer("used_count").default(0).notNull(),
    startsAt: timestamp("starts_at", { withTimezone: true, mode: "date" }),
    endsAt: timestamp("ends_at", { withTimezone: true, mode: "date" }),
    active: boolean().default(true).notNull(),
    createdAt: timestamp("created_at", { withTimezone: true, mode: "date" }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true, mode: "date" }).defaultNow().notNull(),
  },
  (table) => [
    uniqueIndex("discount_codes_code_key").using("btree", sql`upper(code)`),
    check("discount_codes_code_check", sql`code ~ '^[A-Z0-9_-]{3,32}$'::text`),
    check("discount_codes_min_subtotal_check", sql`min_subtotal >= 0`),
    check(
      "discount_codes_per_customer_limit_check",
      sql`(per_customer_limit IS NULL) OR (per_customer_limit > 0)`,
    ),
    check(
      "discount_codes_percentage",
      sql`(kind <> 'percentage'::discount_kind) OR ((value >= 1) AND (value <= 100))`,
    ),
    check("discount_codes_usage_limit_check", sql`(usage_limit IS NULL) OR (usage_limit > 0)`),
    check("discount_codes_value_check", sql`value >= 0`),
  ],
);

